local _originalLength = 389084
local _decodedParts = {}
for _, _cp in utf8.codes(_hanPayload) do
    local _value
    if _cp >= 0x4E00 and _cp <= 0x9FFF then
        _value = _cp - 0x4E00
    elseif _cp >= 0x20000 and _cp <= 0x2A6DF then
        _value = _cp - 0x20000 + 0x5200
    elseif _cp >= 0x2A700 and _cp <= 0x2AE1F then
        _value = _cp - 0x2A700 + 0xF8E0
    else
        error("Invalid Han payload code point")
    end
    local _firstIndex = #_decodedParts * 2 + 1
    local _cipherFirst = math.floor(_value / 256)
    local _cipherSecond = _value % 256
    local _first = (_cipherFirst - ((_firstIndex * 73 + 41) % 256)) % 256
    local _secondIndex = _firstIndex + 1
    local _second = (_cipherSecond - ((_secondIndex * 73 + 41) % 256)) % 256
    _decodedParts[#_decodedParts + 1] = string.char(_first, _second)
end
local _source = table.concat(_decodedParts):sub(1, _originalLength)
local _loader = loadstring or load
if type(_loader) ~= "function" then
    error("Executor không hỗ trợ loadstring/load.")
end
local _chunk, _loadError = _loader(_source)
if not _chunk then
    error(_loadError or "Không thể giải mã/nạp script.")
end
_chunk()
